INSERT INTO `bird_transfers` (`id`, `batch_id`, `from_shed_id`, `to_shed_id`, `quantity`, `transfer_date`, `notes`, `status`, `created_by`, `created_at`) VALUES (1,5,5,4,800,'2026-10-17','Reducing stocking density','posted',1,'2026-11-01 16:57:40');
