LOCK TABLES `blog_posts` WRITE;
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `author_id`, `meta_title`, `meta_description`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'Preparing a shed before new chicks arrive','preparing-a-shed-before-new-chicks-arrive','farming_tips','A clean, warm, dry shed is the cheapest health programme you can buy. Here is what we do before every placement.','<p>The first week sets the tone for the whole batch. Most of what goes wrong later can be traced back to a shed that was not ready.</p><h2>Clean first, then disinfect</h2><p>Remove all old litter, wash down every surface and let the shed dry. Disinfectant does little on a dirty surface, so cleaning comes first.</p><h2>Warm the floor, not just the air</h2><p>Start the brooders well before the chicks arrive so that the litter has warmed through. Chicks lose heat through their feet.</p><ul><li>Check drinker lines and flush them</li><li>Spread fresh, dry litter evenly</li><li>Set out extra feeders for the first days</li></ul><p>Then watch the chicks: if they huddle they are cold, and if they crowd the walls they are too warm.</p>','images/site/chicks-brooder.jpg',1,NULL,NULL,'published','2026-10-27 21:57:32','2026-11-01 16:57:32',NULL,NULL),(2,'Reading daily mortality without panic','reading-daily-mortality-without-panic','bird_health','Some losses are normal. The trend matters more than any single day, and that is why we write it down.','<p>Every flock loses some birds. What matters is whether today looks different from last week, which you can only tell if you record it each day.</p><h2>Record shed by shed</h2><p>A rise in one shed points to something local, such as a blocked drinker line or poor air. A rise across every shed points to something wider, such as feed or disease.</p><blockquote>A number written down today is the warning you get tomorrow.</blockquote><p>If losses climb for two or three days running, call your veterinarian rather than waiting.</p>','images/site/hen-closeup.jpg',1,NULL,NULL,'published','2026-10-11 21:57:32','2026-11-01 16:57:32',NULL,NULL),(3,'Why vaccination timing matters','why-vaccination-timing-matters','vaccination','A vaccine given late, or given badly, may not protect the flock. Follow your veterinarian\'s schedule and keep a record.','<p>A vaccination programme only works when each dose is given at the right age and handled correctly. Your veterinarian will set a schedule for local disease risks, and it should be written down before the chicks arrive.</p><h2>When giving vaccine in water</h2><ul><li>Keep vaccine cold until the moment it is used</li><li>Use clean water with no disinfectant in the line</li><li>Make sure every bird can reach a drinker</li></ul><p>Record the date, the batch and the lot number. If a problem shows up later, those records are the first thing your veterinarian will ask for.</p>','images/site/chicks-box.jpg',1,NULL,NULL,'published','2026-09-25 21:57:32','2026-11-01 16:57:32',NULL,NULL),(4,'Cutting feed waste without cutting growth','cutting-feed-waste-without-cutting-growth','feed_nutrition','Feed is the largest cost on most poultry farms. Small daily losses add up quickly.','<p>Feed is usually the biggest single cost in raising birds, so waste shows up straight away in your margin.</p><h2>Where feed goes missing</h2><ul><li>Feeders set too low, so birds scratch feed onto the litter</li><li>Feeders filled too full</li><li>Damp or stale feed that birds refuse</li><li>Rodents and wild birds</li></ul><p>Raise feeder height as the birds grow, keep bags dry and off the floor, and weigh what goes out each day. You cannot manage waste you do not measure.</p>','images/site/layer-house.jpg',1,NULL,NULL,'published','2026-09-09 21:57:32','2026-11-01 16:57:32',NULL,NULL),(5,'What buyers look for in table eggs','what-buyers-look-for-in-table-eggs','industry','Shops and bakeries care about the same few things: freshness, clean shells and steady supply.','<p>Whether you sell to a corner shop or a bakery, buyers tend to ask for the same things.</p><h2>Freshness and clean shells</h2><p>Collect often, store somewhere cool, and sell oldest first. Remove cracked and dirty eggs before packing, because a single bad tray costs more than it saves.</p><h2>Reliable supply</h2><p>A buyer who can count on you each week is worth more than one who pays a little extra once. Keep daily records of what each house produces so you know what you can promise.</p>','images/site/eggs-tray.jpg',1,NULL,NULL,'published','2026-08-24 21:57:32','2026-11-01 16:57:32',NULL,NULL);
UNLOCK TABLES;

