INSERT INTO `content_blocks` (`id`, `block_type`, `title`, `summary`, `icon`, `image`, `sort_order`, `is_published`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'service','Poultry farming','Broilers and layers raised to contract or for the open market.','bi-house-heart',NULL,0,1,'2026-11-01 16:57:31',NULL,NULL),(2,'service','Chick supply','Uniform day-old chicks, booked around your placement dates.','bi-egg-fried',NULL,1,1,'2026-11-01 16:57:31',NULL,NULL),(3,'service','Egg production','Daily collected, graded eggs by the tray, with regular delivery.','bi-egg',NULL,2,1,'2026-11-01 16:57:31',NULL,NULL),(4,'service','Poultry feed supply','Starter, grower, finisher and layer feed in 50 kg bags.','bi-basket',NULL,3,1,'2026-11-01 16:57:31',NULL,NULL),(5,'service','Farm consultancy','Practical advice on sheds, feeding and flock health from people who farm every day.','bi-chat-dots',NULL,4,1,'2026-11-01 16:57:31',NULL,NULL),(6,'service','Poultry farm management','Day-to-day management and record keeping for owners who want it run properly.','bi-clipboard-check',NULL,5,1,'2026-11-01 16:57:31',NULL,NULL),(7,'facility','Modern poultry sheds','Well-spaced, easy-to-clean houses built for bird comfort.','bi-house-door','images/site/hero-shed.jpg',0,1,'2026-11-01 16:57:31',NULL,NULL),(8,'facility','Automatic feeding systems','Measured feed lines give every bird fair access and limit waste.','bi-gear-wide-connected','images/site/layer-house.jpg',1,1,'2026-11-01 16:57:31',NULL,NULL),(9,'facility','Clean water systems','Nipple drinkers on filtered lines, checked every day.','bi-droplet','images/site/broiler-flock.jpg',2,1,'2026-11-01 16:57:31',NULL,NULL),(10,'facility','Ventilation systems','Fans and inlets keep air fresh and litter dry.','bi-fan','images/site/hen-cage.jpg',3,1,'2026-11-01 16:57:31',NULL,NULL),(11,'facility','Temperature control','Brooding heat for chicks and cooling for the hot months.','bi-thermometer-half','images/site/chicks-brooder.jpg',4,1,'2026-11-01 16:57:31',NULL,NULL),(12,'facility','Biosecurity facilities','Controlled entry, footbaths and disinfection for people and vehicles.','bi-shield-check','images/site/hens-fence.jpg',5,1,'2026-11-01 16:57:31',NULL,NULL),(13,'facility','Veterinary care','A planned vaccination programme and regular visits from a veterinarian.','bi-heart-pulse','images/site/hen-closeup.jpg',6,1,'2026-11-01 16:57:31',NULL,NULL),(14,'why','Healthy poultry','Every batch follows a vaccination programme and daily health checks.',NULL,NULL,0,1,'2026-11-01 16:57:31',NULL,NULL),(15,'why','Quality feed and nutrition','Feed matched to the age and type of the birds.',NULL,NULL,1,1,'2026-11-01 16:57:31',NULL,NULL),(16,'why','Hygienic farming','Clean sheds, clean water and strict entry rules.',NULL,NULL,2,1,'2026-11-01 16:57:31',NULL,NULL),(17,'why','Experienced management','A team that has raised flocks through every season.',NULL,NULL,3,1,'2026-11-01 16:57:31',NULL,NULL),(18,'why','Reliable supply','Planned placements mean we can tell you what is available and when.',NULL,NULL,4,1,'2026-11-01 16:57:31',NULL,NULL),(19,'why','Customer satisfaction','Straight answers, fair weights and deliveries that turn up.',NULL,NULL,5,1,'2026-11-01 16:57:31',NULL,NULL),(20,'process','Quality chick selection','Chicks from selected breeders, checked on arrival.',NULL,NULL,0,1,'2026-11-01 16:57:31',NULL,NULL),(21,'process','Proper feeding','Measured rations for each stage of growth.',NULL,NULL,1,1,'2026-11-01 16:57:31',NULL,NULL),(22,'process','Health monitoring','Daily checks and mortality records.',NULL,NULL,2,1,'2026-11-01 16:57:31',NULL,NULL),(23,'process','Vaccination and care','A scheduled programme for every batch.',NULL,NULL,3,1,'2026-11-01 16:57:31',NULL,NULL),(24,'process','Quality production','Birds and eggs checked before sale.',NULL,NULL,4,1,'2026-11-01 16:57:31',NULL,NULL),(25,'process','Product delivery','On time, to your door or dock.',NULL,NULL,5,1,'2026-11-01 16:57:31',NULL,NULL);
