INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `summary`, `description`, `image`, `price`, `price_unit`, `availability`, `track_stock`, `stock_quantity`, `avg_cost`, `is_published`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,1,'Broiler Chickens','broiler-chickens','Market-ready broilers, weighed and delivered to order.','Our broilers reach market weight in about six weeks on a measured starter and finisher programme. Each batch has a full record of feed, vaccinations and health checks.\n\nAvailable in full or part loads for shops, restaurants and wholesalers.','images/site/broiler-flock.jpg',480.00,'bird','in_stock',0,0.000,0.0000,1,0,'2026-11-01 16:57:31',NULL,NULL),(2,1,'Layer Chickens','layer-chickens','Point-of-lay pullets, vaccinated and ready for your layer house.','Well-grown pullets raised on a complete vaccination programme and sold close to point of lay.\n\nWe can advise on housing and feeding for the first weeks after delivery.','images/site/hens-field.jpg',1450.00,'bird','limited',0,0.000,0.0000,1,1,'2026-11-01 16:57:31',NULL,NULL),(3,2,'Day-Old Chicks','day-old-chicks','Healthy, uniform chicks from selected breeders.','Broiler and layer chicks selected for vigour and uniformity, delivered in ventilated boxes.\n\nBook ahead: chick placements are planned around your shed availability.','images/site/chicks-box.jpg',85.00,'chick','on_order',0,0.000,0.0000,1,2,'2026-11-01 16:57:31',NULL,NULL),(4,3,'Fresh Eggs','fresh-eggs','Graded table eggs collected every day from our layer houses.','Eggs are collected daily, checked, and only sound eggs are packed. Available by the tray for shops, bakeries and caterers.\n\nRegular weekly deliveries can be arranged.','images/site/eggs-tray.jpg',780.00,'tray of 30','in_stock',0,0.000,0.0000,1,3,'2026-11-01 16:57:31',NULL,NULL),(5,4,'Poultry Feed','poultry-feed','Starter, grower, finisher and layer feed in 50 kg bags.','The same feed programme we use on our own farms, available in 50 kg bags.\n\nAsk us which feed fits the age and type of your birds.','images/site/layer-house.jpg',3100.00,'50 kg bag','in_stock',0,0.000,0.0000,1,4,'2026-11-01 16:57:31',NULL,NULL),(6,5,'Poultry Manure','poultry-manure','Well-rotted manure for fields, orchards and nurseries.','Composted litter from our sheds, sold by the trolley load to growers nearby. Collection from the farm or delivery by arrangement.','images/site/hens-fence.jpg',NULL,NULL,'limited',0,0.000,0.0000,1,5,'2026-11-01 16:57:31',NULL,NULL);
UNLOCK TABLES;

