INSERT INTO `testimonials` (`id`, `customer_name`, `customer_title`, `image`, `feedback`, `rating`, `is_published`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'Ahmed Raza','Raza Poultry Traders',NULL,'The birds arrive even in weight and in good condition. We have not had to chase a delivery in the two years we have bought from them.',5,1,0,'2026-11-01 16:57:32',NULL,NULL),(2,'Nadia Malik','Fresh Mart Stores',NULL,'Our customers notice how fresh the eggs are. Weekly deliveries come on the day they promise.',5,1,0,'2026-11-01 16:57:32',NULL,NULL),(3,'Kamran Shah','Shah Live Birds',NULL,'Clear pricing, honest weights, and they tell you early if a batch will be late.',4,1,0,'2026-11-01 16:57:32',NULL,NULL);
